SELECT * FROM blog_trending
WHERE post_id = #{postId}
  AND date >= #{dateStart}
  AND date < #{dateEnd}

SELECT * FROM blog_trending
WHERE post_id IN

    #{postId}

  AND date >= #{dateStart}
  AND date < #{dateEnd}

SELECT bt.* FROM blog_trending bt
INNER JOIN (
    SELECT post_id, MAX(date) as max_date
    FROM blog_trending
    WHERE date >= #{dateStart} AND date < #{dateEnd}
    GROUP BY post_id
) latest ON bt.post_id = latest.post_id AND bt.date = latest.max_date
WHERE bt.date >= #{dateStart} AND bt.date < #{dateEnd}
ORDER BY bt.score DESC
